<# Tests scripting Save on a disposable #72-shaped book, including save-with-errors. #>
[CmdletBinding()]
param([Parameter(Mandatory)][string]$FbeExe,[ValidateSet('valid','nested','user-book')][string]$Case='nested',[string]$OriginalBook,[ValidateSet('none','source','validate')][string]$After='none',[ValidateSet('save','save-as','normal-save','normal-save-as')][string]$Operation='save',[int]$TimeoutSeconds=90)
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'RuntimeTestIsolation.ps1')
$iso=New-IsolatedFbeRuntime -FbeExe $FbeExe -Name 'issue72-save';$passed=$false
$names=@('FBE_NEXT_TEST_MODE','FBE_NEXT_TEST_SCENARIO','FBE_NEXT_SCRIPT_API_ROOT','FBE_NEXT_TEST_SAVE_PATH','FBE_NEXT_TEST_ISSUE72_PRIOR');$old=@{};foreach($name in $names){$old[$name]=[Environment]::GetEnvironmentVariable($name,'Process')}
try {
 $null=New-IsolatedFbeSettingsSeed -Isolation $iso -StartupScriptsDirectory (Join-Path $iso.Root 'empty-scripts')
 $fragment=if($Case -eq 'nested'){'<subtitle><strong><p id="probe">First</p><p>Second</p></strong></subtitle>'}else{'<p id="probe">First <strong>bold</strong> text.</p><p>Second</p>'}
 $xml='<?xml version="1.0" encoding="utf-8"?><FictionBook xmlns="http://www.gribuser.ru/xml/fictionbook/2.0" xmlns:l="http://www.w3.org/1999/xlink"><description><title-info><genre>prose</genre><author><nickname>Test</nickname></author><book-title>Issue72 Save</book-title><lang>en</lang></title-info><document-info><author><nickname>Test</nickname></author><date value="2026-01-01">2026</date><id>issue72-save</id><version>1.0</version></document-info></description><body><section id="target">'+$fragment+'<p><a l:href="#target">Link</a></p><image l:href="#cover"/></section></body><binary id="cover" content-type="image/png">iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a3ioAAAAASUVORK5CYII=</binary></FictionBook>'
 $fixture=Join-Path $iso.Root 'input.fb2';if($Case -eq 'user-book'){if(-not $OriginalBook){throw 'OriginalBook is required.'};Copy-Item -LiteralPath $OriginalBook -Destination $fixture}else{[IO.File]::WriteAllText($fixture,$xml,[Text.UTF8Encoding]::new($false))};$beforeHash=(Get-FileHash -LiteralPath $fixture).Hash
 $trace=Join-Path $iso.Root 'save-state.txt';$target=if($Operation -in @('save','normal-save')){$fixture}else{Join-Path $iso.Root 'save-as.fb2'}
 $script='function Run(){var e=window.external,b=document.getElementById("fbw_body"),ps=b.getElementsByTagName("P"),p=null,saved=false,error="";for(var i=0;i<ps.length;i++){if(String(ps[i].innerText).indexOf("First")>=0){p=ps[i];break;}}if(!p)throw new Error("body paragraph missing");p.insertAdjacentText("beforeEnd"," ISSUE72_SAVE_MARKER ");var before=String(b.innerHTML),dirtyBefore=e.IsDocumentModified();try{saved=!!@@CALL@@;}catch(ex){error=String(ex.message||ex.description||ex);}var after=String(b.innerHTML),dirtyAfter=e.IsDocumentModified();e.WriteTextFile(@@TRACE@@,"saved="+(saved?1:0)+"\ndirty-before="+(dirtyBefore?1:0)+"\ndirty-after="+(dirtyAfter?1:0)+"\nbody-same="+(before===after?1:0)+"\nmarker="+(after.indexOf("ISSUE72_SAVE_MARKER")>=0?1:0)+"\nerror="+error+"\n");}'
 $call=if($Operation -eq 'save'){'e.SaveCurrentDocument()'}else{'e.SaveCurrentDocumentAs('+($target | ConvertTo-Json -Compress)+',false)'};$script=$script.Replace('@@CALL@@',$call).Replace('@@TRACE@@',($trace | ConvertTo-Json -Compress));[IO.File]::WriteAllText((Join-Path $iso.Root 'probe.js'),$script,[Text.UTF8Encoding]::new($false))
 # corpus selects YES for the validation prompt, exercising save with errors.
 [IO.File]::WriteAllText((Join-Path $iso.Root 'suite.xml'),'<suite><step name="issue72-save" script="probe.js" corpus="1"/></suite>',[Text.UTF8Encoding]::new($false))
 $env:FBE_NEXT_TEST_MODE='1';$env:FBE_NEXT_TEST_SCENARIO=if($Operation -like 'normal-*'){"issue72-$Operation"}else{'binary-scripting-compatibility'};$env:FBE_NEXT_SCRIPT_API_ROOT=$iso.Root;$env:FBE_NEXT_TEST_SAVE_PATH=$target;$env:FBE_NEXT_TEST_ISSUE72_PRIOR=if($After -eq 'none'){$null}else{$After};$report=Join-Path $iso.Root 'report.txt'
 $process=Start-Process $iso.Exe -WorkingDirectory $iso.Root -ArgumentList @('--portable','-b',('"'+$report+'"'),('"'+$fixture+'"')) -WindowStyle Hidden -PassThru
 $code=Wait-IsolatedFbeProcess -Process $process -Isolation $iso -Scenario 'issue72-save' -Report $report -TimeoutSeconds $TimeoutSeconds
 if($code -ne 0 -or !(Test-Path -LiteralPath $report) -or ($Operation -notlike 'normal-*' -and !(Test-Path -LiteralPath $trace))){throw "Missing or failed save probe: exit=$code"}
 $result=Get-Content -LiteralPath $report -Raw;$state=if($Operation -like 'normal-*'){$result}else{Get-Content -LiteralPath $trace -Raw};Write-Host "case=$Case operation=$Operation`n$result`n$state"
 if(($After -ne 'none' -and $state -notmatch '(?m)^prior-safe=1\r?$') -or $result -notmatch 'result=PASS' -or $state -notmatch '(?m)^dirty-before=1\r?$' -or $state -notmatch '(?m)^marker=1\r?$'){throw 'Save changed live content or failed to report.'}
 if($state -match '(?m)^saved=0\r?$') {
  if($Case -eq 'valid' -or $state -notmatch '(?m)^body-same=1\r?$' -or $state -notmatch '(?m)^dirty-after=1\r?$' -or (Get-FileHash -LiteralPath $fixture).Hash -ne $beforeHash -or ($Operation -in @('save-as','normal-save-as') -and (Test-Path -LiteralPath $target))){throw 'Save refusal did not preserve the original and dirty edit.'}
 } elseif($state -match '(?m)^saved=1\r?$') {
  if($Case -eq 'user-book'){throw 'INCONCLUSIVE: saved original-book copy requires a full semantic comparison.'}
  if($Operation -in @('save-as','normal-save-as') -and (Get-FileHash -LiteralPath $fixture).Hash -ne $beforeHash){throw 'Save As modified the original.'};$saved=[Xml.XmlDocument]::new();$saved.XmlResolver=$null;$saved.Load($target);$ns=[Xml.XmlNamespaceManager]::new($saved.NameTable);$ns.AddNamespace('f','http://www.gribuser.ru/xml/fictionbook/2.0')
  $body=$saved.SelectSingleNode('/f:FictionBook/f:body',$ns);if(!$body){throw 'Saved body missing.'};$paragraphs=@($body.SelectNodes('.//f:p',$ns));if($paragraphs.Count -ne 3 -or $body.InnerText -notmatch 'First.*ISSUE72_SAVE_MARKER.*Second.*Link'){throw 'Saved text or paragraph count changed.'}
  $link=$body.SelectSingleNode('.//f:a',$ns);$image=$body.SelectSingleNode('.//f:image',$ns);$binary=$saved.SelectSingleNode('/f:FictionBook/f:binary',$ns)
  if(!$link -or $link.GetAttribute('href','http://www.w3.org/1999/xlink') -cne '#target' -or !$image -or $image.GetAttribute('href','http://www.w3.org/1999/xlink') -cne '#cover' -or !$binary -or $binary.GetAttribute('id') -cne 'cover' -or $binary.GetAttribute('content-type') -cne 'image/png' -or [Convert]::ToBase64String([Convert]::FromBase64String($binary.InnerText)) -cne 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a3ioAAAAASUVORK5CYII='){throw 'Saved link, image or binary changed.'}
  if($Case -eq 'nested' -and !$body.SelectSingleNode('.//f:subtitle/f:strong/f:p',$ns)){throw 'Saved subtitle/strong/paragraph structure changed.'}
  if($Case -eq 'valid' -and !$body.SelectSingleNode('.//f:p/f:strong',$ns)){throw 'Saved inline formatting changed.'}
 } else {throw 'Missing save result.'}
 $passed=$true;Write-Host "Issue72 $Operation $Case PASS."
} finally {foreach($name in $names){[Environment]::SetEnvironmentVariable($name,$old[$name],'Process')};Complete-IsolatedFbeRuntime -Isolation $iso -Passed $passed}
